sp_widget.client_script:
api.controller = function() {

    var c = this;

    c.processing = false;

    c.successMessage = "";
    c.errorMessage = "";


    // ----------------------------------
    // INITIAL FORM VALUES
    // ----------------------------------

    c.form = {
        status:
            c.data.case.status_value || 'open',

        resolution_notes: ""
    };


    // ----------------------------------
    // SAVE CASE
    // ----------------------------------

    c.saveCase = function() {

        c.successMessage = "";
        c.errorMessage = "";

        if (c.processing) {
            return;
        }

        c.processing = true;


        c.server.get({

            action: 'save_case',

            sys_id:
                c.data.case.sys_id,

            status:
                c.form.status,

            resolution_notes:
                c.form.resolution_notes

        }).then(function(response) {

            c.processing = false;


            if (response.data.success) {

                c.successMessage =
                    response.data.message;

                c.data.case =
                    response.data.case;

                c.form.status =
                    response.data.case.status_value;

                // Keep notes only when saving draft/update
                c.form.resolution_notes =
                    response.data.case.resolution_notes || "";

            } else {

                c.errorMessage =
                    response.data.message ||
                    "Unable to update HR Case.";
            }

        }, function() {

            c.processing = false;

            c.errorMessage =
                "Unable to update HR Case.";

        });

    };


    // ----------------------------------
    // PROPOSE RESOLUTION
    // ----------------------------------

    c.proposeResolution = function() {

        c.successMessage = "";
        c.errorMessage = "";


        if (
            !c.form.resolution_notes ||
            !c.form.resolution_notes.trim()
        ) {

            c.errorMessage =
                "Please enter Resolution Notes before proposing the resolution.";

            return;
        }


        if (c.processing) {
            return;
        }


        c.processing = true;


        c.server.get({

            action: 'propose_resolution',

            sys_id:
                c.data.case.sys_id,

            resolution_notes:
                c.form.resolution_notes

        }).then(function(response) {

            c.processing = false;


            if (response.data.success) {

                c.successMessage =
                    response.data.message;

                c.data.case =
                    response.data.case;

                c.form.status =
                    response.data.case.status_value;


                // IMPORTANT:
                // Clear Agent Work Area textarea
                c.form.resolution_notes = "";


            } else {

                c.errorMessage =
                    response.data.message ||
                    "Unable to propose the resolution.";
            }

        }, function() {

            c.processing = false;

            c.errorMessage =
                "Unable to propose the resolution.";

        });

    };

};

sp_widget.css:
.hrcd-page {
  max-width: 1180px;
  margin: 0 auto;
  padding: 38px 25px 60px;
  color: #102052;
  font-family: inherit;
}

/* HEADER */

.hrcd-header {
  display: flex;
  justify-content: space-between;
  align-items: flex-start;
  margin-bottom: 28px;
}

.hrcd-header h2 {
  margin: 0 0 6px;
  font-size: 30px;
  font-weight: 700;
  color: #102052;
}

.hrcd-header p {
  margin: 0;
  font-size: 14px;
  color: #75809b;
}

.hrcd-back {
  color: #1261e8;
  font-size: 14px;
  text-decoration: none;
  margin-top: 10px;
}

.hrcd-back:hover {
  text-decoration: underline;
}


/* SUMMARY CARDS */

.hrcd-summary-grid {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 18px;
  margin-bottom: 22px;
}

.hrcd-summary-card {
  background: #ffffff;
  border: 1px solid #dfe5ef;
  border-radius: 14px;
  padding: 20px;
  min-height: 100px;
  box-shadow: 0 3px 10px rgba(15, 35, 75, 0.05);
}

.hrcd-summary-card span:first-child {
  display: block;
  color: #78849c;
  font-size: 12px;
  margin-bottom: 10px;
}

.hrcd-summary-card strong {
  display: block;
  font-size: 18px;
  color: #102052;
}


/* MAIN GRID */

.hrcd-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
  margin-bottom: 20px;
}


/* GENERAL CARD */

.hrcd-card {
  background: #ffffff;
  border: 1px solid #dfe5ef;
  border-radius: 14px;
  padding: 22px;
  margin-bottom: 20px;
  box-shadow: 0 3px 12px rgba(15, 35, 75, 0.05);
}

.hrcd-card-header {
  margin-bottom: 18px;
}

.hrcd-card-header h3 {
  margin: 0 0 4px;
  font-size: 18px;
  font-weight: 700;
  color: #102052;
}

.hrcd-card-header p {
  margin: 0;
  color: #7a8499;
  font-size: 13px;
}


/* CASE INFORMATION */

.hrcd-info-grid {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 20px;
}

.hrcd-field label {
  display: block;
  margin-bottom: 7px;
  color: #7b8599;
  font-size: 12px;
  font-weight: 500;
}

.hrcd-field > div {
  color: #102052;
  font-size: 14px;
  font-weight: 600;
}

.muted-text {
  color: #9aa3b5 !important;
}


/* EMPLOYEE REQUEST */

.request-box {
  min-height: 110px;
  padding: 16px;
  background: #f7f9fc;
  border: 1px solid #e3e8f1;
  border-radius: 10px;
  color: #293653;
  line-height: 1.6;
  white-space: pre-wrap;
}


/* AGENT WORK AREA */

.work-card {
  border-left: 4px solid #0b8793;
}

.work-grid {
  display: grid;
  grid-template-columns: 280px 1fr;
  gap: 24px;
  align-items: start;
}

.hrcd-field select {
  width: 100%;
  height: 42px;
  padding: 8px 12px;
  background: #ffffff;
  border: 1px solid #d5ddea;
  border-radius: 8px;
  color: #17264e;
  outline: none;
}

.hrcd-field select:focus {
  border-color: #0b8793;
  box-shadow: 0 0 0 2px rgba(11, 135, 147, 0.08);
}

.hrcd-field textarea {
  width: 100%;
  min-height: 120px;
  resize: vertical;
  padding: 12px;
  background: #ffffff;
  border: 1px solid #d5ddea;
  border-radius: 8px;
  color: #17264e;
  outline: none;
}

.hrcd-field textarea:focus {
  border-color: #0b8793;
  box-shadow: 0 0 0 2px rgba(11, 135, 147, 0.08);
}

.hrcd-field small {
  display: block;
  margin-top: 7px;
  color: #8b94a7;
  font-size: 11px;
}


/* BUTTONS */

.action-row {
  display: flex;
  justify-content: flex-end;
  gap: 12px;
  margin-top: 22px;
  padding-top: 18px;
  border-top: 1px solid #edf0f5;
}

.btn-secondary,
.btn-resolve {
  border: 0;
  border-radius: 8px;
  padding: 10px 20px;
  font-size: 13px;
  font-weight: 600;
  cursor: pointer;
  transition: 0.2s;
}

.btn-secondary {
  background: #edf2f7;
  color: #17264e;
}

.btn-secondary:hover {
  background: #e2e8f0;
}

.btn-resolve {
  background: #0b8793;
  color: #ffffff;
}

.btn-resolve:hover {
  background: #076d77;
}


/* STATUS BADGES */

.status-pill {
  display: inline-block !important;
  width: auto;
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 11px !important;
  font-weight: 600;
}

.status-open {
  background: #fff1d8;
  color: #c87800 !important;
}

.status-progress {
  background: #e4efff;
  color: #1261e8 !important;
}

.status-resolved {
  background: #dcf5e7;
  color: #138a50 !important;
}

.status-closed {
  background: #edf0f4;
  color: #626b7a !important;
}


/* PRIORITY */

.priority-pill {
  display: inline-block !important;
  width: auto;
  padding: 5px 11px;
  border-radius: 20px;
  font-size: 11px !important;
  font-weight: 600;
}

.priority-high {
  background: #ffe4e4;
  color: #d93434 !important;
}

.priority-medium {
  background: #fff1d7;
  color: #d88400 !important;
}

.priority-low {
  background: #ddf5e6;
  color: #16834d !important;
}


/* RESOLUTION */

.resolution-box {
  padding: 16px;
  background: #f0faf5;
  border: 1px solid #ccebdc;
  border-radius: 10px;
  color: #275c45;
  line-height: 1.6;
  white-space: pre-wrap;
}


/* MESSAGES */

.hrcd-message {
  margin-top: 20px;
  padding: 14px 16px;
  border-radius: 9px;
  font-size: 13px;
}

.hrcd-message.success {
  background: #e6f7ed;
  border: 1px solid #bce8ce;
  color: #167747;
}

.hrcd-message.error {
  background: #fff0f0;
  border: 1px solid #f2caca;
  color: #c63737;
}


/* RESPONSIVE */

@media (max-width: 900px) {

  .hrcd-summary-grid {
    grid-template-columns: 1fr 1fr;
  }

  .hrcd-grid {
    grid-template-columns: 1fr;
  }

  .work-grid {
    grid-template-columns: 1fr;
  }
}

@media (max-width: 600px) {

  .hrcd-page {
    padding: 25px 15px;
  }

  .hrcd-header {
    flex-direction: column;
    gap: 12px;
  }

  .hrcd-summary-grid {
    grid-template-columns: 1fr;
  }

  .hrcd-info-grid {
    grid-template-columns: 1fr;
  }

  .action-row {
    flex-direction: column;
  }

  .btn-secondary,
  .btn-resolve {
    width: 100%;
  }
}

.status-awaiting {
    background: #fff7ed;
    color: #c2410c;
}

.resolution-date {
    margin-top: 12px;
    color: #64748b;
    font-size: 11px;
}

sp_widget.script:
(function() {

    // ----------------------------------
    // CURRENT USER
    // ----------------------------------

    data.userId = gs.getUserID();
    data.userName = gs.getUserDisplayName();

    data.isHRManager = false;
    data.hasAccess = false;
    data.caseFound = false;

    data.message = "";
    data.success = false;
    data.error = false;

    data.case = {};


    // ----------------------------------
    // HR MANAGER CHECK
    // ----------------------------------

    var currentUser = gs.getUser();

    if (currentUser.isMemberOf('HR Managers')) {
        data.isHRManager = true;
    }


    // ----------------------------------
    // GET CASE SYS_ID
    // ----------------------------------

    var caseSysId = "";

    if (input && input.sys_id) {
        caseSysId = input.sys_id;
    } else {
        caseSysId = $sp.getParameter('sys_id');
    }


    if (!caseSysId) {

        data.message =
            "No HR case was selected.";

        data.error = true;

        return;
    }


    // ----------------------------------
    // LOAD CASE
    // ----------------------------------

    var caseGR =
        new GlideRecord(
            'x_snc_unified_hr_0_hr_case'
        );


    if (!caseGR.get(caseSysId)) {

        data.message =
            "HR Case not found.";

        data.error = true;

        return;
    }


    data.caseFound = true;


    // ----------------------------------
    // ACCESS CHECK
    // ----------------------------------

    if (data.isHRManager) {

        data.hasAccess = true;

    } else {

        var assignmentGroupId =
            caseGR.getValue(
                'assignment_group'
            );

        var assignedToId =
            caseGR.getValue(
                'assigned_to'
            );


        // Directly assigned to logged-in user
        if (assignedToId == data.userId) {

            data.hasAccess = true;

        } else if (assignmentGroupId) {

            // Check whether logged-in HR user
            // belongs to assignment group

            var memberGR =
                new GlideRecord(
                    'sys_user_grmember'
                );

            memberGR.addQuery(
                'user',
                data.userId
            );

            memberGR.addQuery(
                'group',
                assignmentGroupId
            );

            memberGR.setLimit(1);
            memberGR.query();


            if (memberGR.next()) {

                data.hasAccess = true;
            }
        }
    }


    if (!data.hasAccess) {

        data.message =
            "You are not authorized to access this HR case.";

        data.error = true;

        return;
    }


    // ==================================================
    // SAVE UPDATE
    // ==================================================

    if (input &&
        input.action == 'save_case') {

        var requestedStatus =
            (input.status || '')
                .toString();

        var resolutionNotes =
            (input.resolution_notes || '')
                .toString()
                .trim();


        var allowedStatuses = [
            'open',
            'in_progress'
        ];


        if (
            allowedStatuses.indexOf(
                requestedStatus
            ) == -1
        ) {

            data.message =
                "Invalid case status.";

            data.error = true;

        } else {

            caseGR.setValue(
                'status',
                requestedStatus
            );


            if (resolutionNotes) {

                caseGR.setValue(
                    'resolution_notes',
                    resolutionNotes
                );
            }


            caseGR.update();

            data.success = true;

            data.message =
                "HR Case " +
                caseGR.getDisplayValue(
                    'number'
                ) +
                " updated successfully.";
        }
    }


    // ==================================================
    // PROPOSE RESOLUTION
    // ==================================================

    if (input &&
        input.action == 'propose_resolution') {

        var proposedResolution =
            (input.resolution_notes || '')
                .toString()
                .trim();


        if (!proposedResolution) {

            data.message =
                "Please enter Resolution Notes before proposing the resolution.";

            data.error = true;

        } else {

            // Save proposed HR solution
            caseGR.setValue(
                'resolution_notes',
                proposedResolution
            );


            // Move case to employee confirmation
            caseGR.setValue(
                'status',
                'awaiting_employee_confirmation'
            );


            // Record proposal time
            if (
                caseGR.isValidField(
                    'resolution_proposed_on'
                )
            ) {

                caseGR.setValue(
                    'resolution_proposed_on',
                    new GlideDateTime().getValue()
                );
            }


            caseGR.update();


            data.success = true;

            data.message =
                "Resolution proposed for HR Case " +
                caseGR.getDisplayValue(
                    'number'
                ) +
                ". Waiting for employee confirmation.";
        }
    }


    // ----------------------------------
    // RELOAD LATEST RECORD
    // ----------------------------------

    caseGR.get(caseSysId);


    // ----------------------------------
    // CREATED DATE
    // ----------------------------------

    var createdOn =
        caseGR.getDisplayValue(
            'created_on'
        );


    // Fallback for existing records
    if (!createdOn) {

        createdOn =
            caseGR.getDisplayValue(
                'sys_created_on'
            );
    }


    // ----------------------------------
    // STATUS LABEL
    // ----------------------------------

    var statusValue =
        caseGR.getValue(
            'status'
        );

    var statusLabel =
        caseGR.getDisplayValue(
            'status'
        );


    // Friendly fallback for custom choice
    if (
        statusValue ==
        'awaiting_employee_confirmation'
    ) {

        statusLabel =
            'Awaiting Employee Confirmation';
    }


    // ----------------------------------
    // CASE DETAILS
    // ----------------------------------

    data.case = {

        sys_id:
            caseGR.getUniqueValue(),

        number:
            caseGR.getDisplayValue(
                'number'
            ),

        requested_by:
            caseGR.getDisplayValue(
                'request_by'
            ),

        subject:
            caseGR.getDisplayValue(
                'subject'
            ),

        category:
            caseGR.getDisplayValue(
                'category'
            ),

        priority:
            caseGR.getDisplayValue(
                'priority'
            ),

        assignment_group:
            caseGR.getDisplayValue(
                'assignment_group'
            ),

        assigned_to:
            caseGR.getDisplayValue(
                'assigned_to'
            ),

        status:
            statusLabel,

        status_value:
            statusValue,

        description:
            caseGR.getDisplayValue(
                'description'
            ),

        resolution_notes:
            caseGR.getDisplayValue(
                'resolution_notes'
            ),

        resolution_proposed_on:
            caseGR.getDisplayValue(
                'resolution_proposed_on'
            ),

        rejection_feedback:
            caseGR.getDisplayValue(
                'rejection_feedback'
            ),

        resolved_on:
            caseGR.getDisplayValue(
                'resolved_on'
            ),

        closed_on:
            caseGR.getDisplayValue(
                'closed_on'
            ),

        created_on:
            createdOn

    };

})();
